MATCH (lakeRef:Lake {name:"Lake Teletskoe"})
// Rivers that flow directly into Lake Teletskoe
MATCH (river:River)-[:flowsInto]->(lakeRef)
// The country that these rivers pass through
MATCH (river)-[:flowsThrough]->(country:Country)
WITH country
// All rivers that also flow through this country
MATCH (river2:River)-[:flowsThrough]->(country)
// Lakes that are downstream of those rivers
MATCH (lake2:Lake)<-[:flowsInto]-(river2)
RETURN max(toFloat(lake2.area_km2)) AS max_area

MATCH (m:Mountain) 
WHERE toLower(m.description) CONTAINS 'peru' 
RETURN m.name AS mountain, m.elevation_m AS elevation;

MATCH (mr:MountainRange)
WHERE mr.name IN ["Gangotri Group", "Annapurna"]
RETURN mr.name AS mountainRangeName;

MATCH (c:Country) 
WHERE EXISTS { MATCH (:Mountain {name:"Avalanche Peak II"}) } 
  AND EXISTS { MATCH (:Mountain {name:"Sakram"}) } 
RETURN c.name AS countryName, c.capital AS capital
